events=[]
class Values:
 def __iter__(self):
  events.append('iterate')
  return iter([1])
def mark():
 events.append('keyword')
 return 2
def sink(*args,**kw): return args,kw
print(sink(*Values(),flag=mark()),events)

events=[]
def sink(**kw): return kw
class Mapping:
 def keys(self):
  def produce():
   for key in ['a','b']:
    events.append('key:'+key)
    yield key
  return produce()
 def __getitem__(self,key):
  events.append('get:'+key)
  return key.upper()
print(sink(**Mapping()),events)

events=[]
def sink(**kw): events.append('called')
class Mapping:
 def keys(self): return ['a']
 def __getitem__(self,key):
  events.append('get')
  return 2
try: sink(a=1,**Mapping())
except TypeError: print(events)

events=[]
def sink(**kw): events.append('called')
class Mapping:
 def keys(self): return [1]
 def __getitem__(self,key):
  events.append('get')
  return 2
try: sink(**Mapping())
except TypeError: print(events)

events=[]
class Values:
 def __iter__(self):
  events.append('iterate')
  return iter([1])
class Mapping:
 def keys(self):
  events.append('keys')
  return ['end']
 def __getitem__(self,key):
  events.append('get:'+key)
  return 2
def sink(*args,**kw):
 events.append('call')
 return args,kw
print(sink(*Values(),**Mapping()),events)

class Base:
 def value(self): return 3
class Child(Base):
 def value(self): return super(*[]).value()+1
print(Child().value())
